        move("cold_run_song_charge_nebo (CALL) — SC.the_readback(the_table) = %s (32:15's Jeshurun — song_jeshurun_fat_kicked_declared the kind, by reference); MISHNAH AVOT 3:6 THE CASE at 346:2 — THE SHEKHINAH AMONG TEN who sit and occupy themselves with the Torah (and five, and three, and two, and one): THE PARAMETER the_shekhinah_among_ten; cold_run_hear_o_israel (CALL) — HI.the_creed(hear_o_israel) = %s (the creed by reference)" % (SV(SC_TABLE, 40), SV(HI_HEAR, 40)), "20b's OWED POINTER ROW at 33:5 PAID HERE — 346:2 read at chapter 32 for 32:3's teaching, read whole here in its own piska: the readback's POINTER ROW 33:5, grade R; THE WRITE king_in_jeshurun_when_the_heads_gathered_declared — a STATUS on israel_people")
        dat("THE WRITE king_in_jeshurun_when_the_heads_gathered_declared, a STATUS on israel_people at %s; THE PARAMETER the_shekhinah_among_ten — Mishnah Avot 3:6 THE CASE; the readback's POINTER ROW 33:5 (grade R — 20b's owed row paid)" % D1)
        return out("there was a king in Jeshurun when the heads of the people gathered (33:5) — Jeshurun Israel (Onkelos; 32:15's rule by CALL), the Shekhinah among ten the case (Avot 3:6 — a parameter), 20b's owed pointer row PAID (grade R): THE WRITE king_in_jeshurun_when_the_heads_gathered_declared, a STATUS on Israel", ['king_in_jeshurun_when_the_heads_gathered_declared'])
