def the_reuben_and_judah(case, data):
    """F3 — Deut 33:6-7 — ONE LINE blessing_reuben_and_judah_declared (SPEECH) writing reuben_to_live_and_not_die_blessed (a STATUS on reuben) and judahs_voice_heard_brought_to_his_people_blessed (a STATUS on judah) — the sons' own ledgers (Genesis 49's demoted and scepter_held the entries before); Bilhah and Tamar the tape's (family by CALL), Reuben's number the censuses' (bamidbar and second_census by CALL); Sanhedrin 10:1 the case; SIMEON under Judah — erection, balak and midian by CALL, a DATA row, no write"""
