def the_levi(case, data):
    """F4 — Deut 33:8-11 — ONE LINE blessing_levi_declared (SPEECH) writing levi_thummim_and_urim_proved_at_massah_blessed, levi_father_and_mother_unseen_covenant_kept, levi_teaches_jacob_incense_and_whole_offering and levi_substance_blessed_loins_of_his_foes_smitten (STATUSES on levi — Genesis 49:7's scattered_in_israel the entry before, the scattering turned to teaching); the Urim (vestments by CALL), Massah and Meribah RUN CITATIONS (exodus_story, chukat, hear_o_israel by CALL), the calf's sword (erection by CALL; priesthood, shelach by CALL), every ruling from the Levites' mouth (refuge_war_family, courts_prophet by CALL), the incense and the whole offering (incense_shekel, offerings by CALL), Korah the riser and the gifts (korach by CALL); Shekalim 1:1 the case"""
